// Parses flags recognized by deno from the argument list, returning the parsed
// flags along with the remaining (non-flag) arguments.
pub fn set_flags(args: Vec<String>) -> (DenoFlags, Vec<String>) {
  let mut flags = DenoFlags {
    help: false,
    log_debug: false,
    version: false,
    reload: false,
    allow_write: false,
    allow_net: false,
